import React, { useEffect, useRef } from 'react';
import './App.css';

export function Stages({ stagePass }) {
  const stageDivs = useRef([]);

  useEffect(() => {
    if (stageDivs.current.length > 0) {
      stageDivs.current.forEach(div => {
        div.classList.remove('current');
      });
      if (stageDivs.current[stagePass]) {
        stageDivs.current[stagePass].classList.add('current');
      }
    }
  }, [stagePass]);

  return (
    <div className="game_stages">
      <div className="stage block" ref={el => (stageDivs.current[9] = el)} id="9">
        1.000.000
      </div>
      <div className="stage" ref={el => (stageDivs.current[8] = el)} id="8">
        500.000
      </div>
      <div className="stage" ref={el => (stageDivs.current[7] = el)} id="7">
        250.000
      </div>
      <div className="stage block" ref={el => (stageDivs.current[6] = el)} id="6">
        125.000
      </div>
      <div className="stage" ref={el => (stageDivs.current[5] = el)} id="5">
        64.000
      </div>
      <div className="stage" ref={el => (stageDivs.current[4] = el)} id="4">
        32.000
      </div>
      <div className="stage block" ref={el => (stageDivs.current[3] = el)} id="3">
        16.000
      </div>
      <div className="stage" ref={el => (stageDivs.current[2] = el)} id="2">
        8.000
      </div>
      <div className="stage" ref={el => (stageDivs.current[1] = el)} id="1">
        1.000
      </div>
      <div className="line"></div>
      <div className="total_take">tOtal: 16.000$</div>
    </div>
  );
}
